from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind, step = parts[0], int(parts[1])
    weekdays = {name: i for i, name in enumerate(
        ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
    )}

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        selected = sorted(weekdays[name] for name in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())
        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1

        while len(result) < count:
            year, zero_based_month = divmod(month_index, 12)
            month = zero_based_month + 1
            first_weekday, days_in_month = monthrange(year, month)

            if len(parts) == 3:
                requested_day = int(parts[2])
                day = days_in_month if requested_day == -1 else requested_day
            else:
                occurrence = int(parts[2])
                weekday = weekdays[parts[3]]

                if occurrence == -1:
                    last_weekday = (first_weekday + days_in_month - 1) % 7
                    day = days_in_month - (last_weekday - weekday) % 7
                else:
                    day = (
                        1 + (weekday - first_weekday) % 7
                        + 7 * (occurrence - 1)
                    )

            if day <= days_in_month:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())

            month_index += step

        return result

    month, day = map(int, parts[2].split("-"))
    year = first.year

    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= first:
                result.append(candidate.isoformat())
        year += step

    return result
